insert into prep.summaries (id, grp, free, sort, data) values
  ('a3-admin', 'A3', false, 0, '{"id":"a3-admin","group":"A3","topics":["A3-ADMIN"],"icon":"🏛️","title":"พ.ร.บ.ระเบียบบริหารราชการแผ่นดิน ① โครงสร้าง & ส่วนกลาง","hub":"บริหารราชการแผ่นดิน","hubSub":"พ.ศ. 2534 · ผู้รักษาการ นายกฯ","intro":"ภาพรวมทั้งฉบับ ส่วนกลาง กฎหมายที่ใช้ตั้ง-ยุบส่วนราชการ และ ก.พ.ร. เรื่องมอบอำนาจ รักษาราชการแทน และภูมิภาค อยู่ในแผนผัง ②","branches":[{"id":"parts","icon":"🧩","tone":"pink","title":"แบ่งการบริหาร","ref":"ม.4 · ม.7","big":"3","unit":"ส่วน","must":true,"sub":"ส่วนกลาง · ส่วนภูมิภาค · ส่วนท้องถิ่น","ask":"บริหารราชการแผ่นดินแบ่งเป็นกี่ส่วน","blocks":[{"k":"table","head":["ส่วน","หลักการ","ประกอบด้วย"],"rows":[["ส่วนกลาง (ม.7)","รวมอำนาจ","สำนักนายกรัฐมนตรี · กระทรวง (หรือทบวงที่เทียบเท่ากระทรวง) · ทบวง · กรม"],["ส่วนภูมิภาค (ม.51)","แบ่งอำนาจ","จังหวัด · อำเภอ"],["ส่วนท้องถิ่น (ม.70)","กระจายอำนาจ","อบจ. · เทศบาล · สุขาภิบาล · อื่นตามที่กฎหมายกำหนด (เช่น อบต. กทม. เมืองพัทยา)"]]},{"k":"pairs","items":[{"a":"รวมอำนาจ","b":"อำนาจตัดสินใจอยู่ที่ส่วนกลาง (สำนักนายกฯ กระทรวง กรม)"},{"a":"แบ่งอำนาจ","b":"ส่วนกลางแบ่งอำนาจให้คนของตนที่ส่งไปประจำภูมิภาค เช่น ผู้ว่าฯ นายอำเภอ (สังกัดมหาดไทย) ยังอยู่ใต้บังคับบัญชาส่วนกลาง"},{"a":"กระจายอำนาจ","b":"มอบอำนาจให้ท้องถิ่นดูแลตัวเอง ประชาชนเลือกผู้บริหารและสภาเอง เป็นนิติบุคคลแยกจากส่วนกลาง"}]},{"k":"memo","t":"\"กลาง-รวม · ภูมิ-แบ่ง · ถิ่น-กระจาย\""},{"k":"list","items":[{"icon":"⚖️","t":"สำนักนายกฯ กระทรวง ทบวง กรม เป็นนิติบุคคล","d":"สำนักนายกรัฐมนตรีมีฐานะเป็นกระทรวง (ม.7)"},{"icon":"🗺️","t":"ภูมิภาค: จังหวัดเป็นนิติบุคคล อำเภอไม่เป็น","d":"รายละเอียดอยู่ในแผนผัง ②"},{"icon":"🎯","t":"หลักการบริหาร ม.3/1","d":"ประโยชน์สุขของประชาชน ผลสัมฤทธิ์ ประสิทธิภาพ คุ้มค่า ลดขั้นตอน ลดภารกิจที่ไม่จำเป็น กระจายอำนาจ ตอบสนองประชาชน โดยมีผู้รับผิดชอบต่อผลของงาน"}]},{"k":"oops","t":"ไม่มี \"ระเบียบบริหารราชการส่วนรวม\" และจังหวัดเป็นภูมิภาค แต่ อบจ. เป็นท้องถิ่น ชื่อคล้ายกันคนละส่วน"},{"k":"past","src":"สพฐ. ปี 2566","q":"ข้อใดไม่ใช่การจัดระเบียบบริหารราชการแผ่นดิน","choices":["ระเบียบบริหารราชการส่วนรวม","ระเบียบบริหารราชการส่วนกลาง","ระเบียบบริหารราชการส่วนภูมิภาค","ระเบียบบริหารราชการส่วนท้องถิ่น"],"a":0,"why":"ม.4 แบ่งไว้ 3 ส่วนเท่านั้น คือ ส่วนกลาง ส่วนภูมิภาค ส่วนท้องถิ่น"}]},{"id":"laws","icon":"📜","tone":"pea","title":"ตั้ง-รวม-โอน-เปลี่ยนชื่อ-ยุบ","ref":"ม.8–8 ฉ","big":"พ.ร.ฎ.","hot":true,"ask":"เปลี่ยนชื่อกระทรวง ทบวง กรม ตราเป็นกฎหมายใด","sub":"เปลี่ยนชื่อ ยุบ = พ.ร.ฎ. · ตั้ง รวม โอน = พ.ร.บ. (รวม/โอนที่ไม่เพิ่มตำแหน่ง = พ.ร.ฎ.)","blocks":[{"k":"table","head":["การกระทำ","ตราเป็น"],"rows":[["จัดตั้ง รวม หรือโอนกระทรวง ทบวง กรม (ม.8)","พ.ร.บ."],["รวมหรือโอน โดยไม่เพิ่มตำแหน่งหรืออัตรา (ม.8 ทวิ)","พ.ร.ฎ."],["เปลี่ยนชื่อส่วนราชการ (ม.8 ตรี)","พ.ร.ฎ."],["ยุบส่วนราชการ (ม.8 จัตวา)","พ.ร.ฎ."],["แบ่งส่วนราชการภายในกรม / สำนักงานรัฐมนตรี (ม.8 ฉ)","กฎกระทรวง (รัฐมนตรีเจ้าสังกัดออก)"],["ตั้ง ยุบ เปลี่ยนเขตจังหวัด (ม.52)","พ.ร.บ."],["ตั้ง ยุบ เปลี่ยนเขตอำเภอ (ม.61)","พ.ร.ฎ."]]},{"k":"list","items":[{"icon":"🔒","t":"รวม/โอนตาม ม.8 ทวิ ห้ามเพิ่มตำแหน่งหรืออัตรา 3 ปี","d":"สำนักงาน ก.พ. และสำนักงบประมาณเป็นผู้ตรวจสอบ"},{"icon":"💵","t":"ยุบส่วนราชการ คนที่ต้องพ้นจากราชการได้เงินชดเชยตาม พ.ร.ฎ. ยุบนั้น","d":"หน่วยงานอื่นรับโอนได้ภายใน 30 วันนับแต่ พ.ร.ฎ. ใช้บังคับ"}]},{"k":"memo","t":"\"ตั้ง-รวม-โอน = บัญญัติ (รวม/โอนไม่เพิ่มคน = กฤษฎีกา) · ชื่อ-ยุบ = กฤษฎีกา · แบ่งในกรม = กฎกระทรวง\" · จังหวัด พ.ร.บ. อำเภอ พ.ร.ฎ."},{"k":"oops","t":"เปลี่ยนชื่อกระทรวงศึกษาธิการ ตราเป็น พ.ร.ฎ. ไม่ใช่ พ.ร.บ. ข้อนี้ในแอปคนตอบ พ.ร.บ. เยอะมาก"}]},{"id":"heads","icon":"🏢","tone":"mint","title":"ใครบังคับบัญชา","ref":"ม.10–32","big":"เลขาฯ รมต.","ask":"สำนักงานรัฐมนตรี ใครเป็นผู้บังคับบัญชา","sub":"สำนักงานรัฐมนตรี = ราชการทางการเมือง","blocks":[{"k":"table","head":["ส่วนราชการ","ผู้บังคับบัญชา","ประเภท"],"rows":[["สำนักนายกรัฐมนตรี","นายกรัฐมนตรี","การเมือง"],["สำนักเลขาธิการนายกรัฐมนตรี","เลขาธิการนายกรัฐมนตรี","การเมือง"],["สำนักเลขาธิการคณะรัฐมนตรี","เลขาธิการคณะรัฐมนตรี","พลเรือนสามัญ"],["กระทรวง","รัฐมนตรีว่าการกระทรวง","การเมือง"],["สำนักงานรัฐมนตรี","เลขานุการรัฐมนตรี","การเมือง"],["สำนักงานปลัดกระทรวง","ปลัดกระทรวง (รองจากรัฐมนตรี)","พลเรือนสามัญ"],["กรม","อธิบดี","พลเรือนสามัญ"],["สำนักงานเลขานุการกรม","เลขานุการกรม","พลเรือนสามัญ"]]},{"k":"list","items":[{"icon":"🪖","t":"กระทรวงที่เกี่ยวกับการทหารและการศึกษา จัดระเบียบตามกฎหมายว่าด้วยการนั้น (ม.19)","d":"กระทรวงอื่นเป็นไปตามกฎหมายปรับปรุงกระทรวง ทบวง กรม"},{"icon":"🧭","t":"กลุ่มภารกิจ: กรมตั้งแต่ 2 กรมขึ้นไป ออกกฎกระทรวงจัดเป็นกลุ่มได้","d":"หัวหน้ากลุ่มภารกิจต้องไม่ต่ำกว่าอธิบดี (ม.21)"},{"icon":"🔍","t":"ผู้ตรวจราชการกระทรวง ทบวง กรม","d":"ตรวจและแนะนำการปฏิบัติราชการ (ม.35)"}]},{"k":"oops","t":"เลขาธิการ ครม. เป็นข้าราชการพลเรือนสามัญ แต่เลขาธิการนายกรัฐมนตรีเป็นข้าราชการการเมือง ข้อสอบชอบสลับกัน"}]},{"id":"pm","icon":"👑","tone":"lem","title":"อำนาจนายกรัฐมนตรี","ref":"ม.11","big":"ยับยั้ง","ask":"นายกฯ ในฐานะหัวหน้ารัฐบาล ทำอะไรกับการปฏิบัติราชการที่ขัดนโยบาย ครม. ได้","sub":"การปฏิบัติราชการที่ขัดนโยบายหรือมติ ครม.","blocks":[{"k":"list","items":[{"icon":"🛑","t":"กำกับการบริหารราชการทั่วไป สั่งให้ชี้แจง ยับยั้ง และสั่งสอบสวนข้อเท็จจริงได้","d":"ทั้งส่วนกลาง ภูมิภาค และท้องถิ่น"},{"icon":"🤝","t":"มอบหมายรองนายกฯ กำกับกระทรวงหนึ่งหรือหลายกระทรวง"},{"icon":"🔀","t":"แต่งตั้งข้าราชการต่างกระทรวงไปดำรงตำแหน่งอีกกระทรวง","d":"ถ้าเป็นระดับอธิบดีขึ้นไป ต้องได้รับอนุมัติจาก ครม."},{"icon":"📏","t":"วางระเบียบปฏิบัติราชการ ใช้บังคับเมื่อ ครม. เห็นชอบ"}]},{"k":"note","t":"ผู้รักษาการตาม พ.ร.บ. นี้ คือนายกรัฐมนตรี (ม.6) · ให้ไว้ 21 สิงหาคม 2534"}]},{"id":"opdc","icon":"⚙️","tone":"lil","title":"ก.พ.ร.","ref":"ม.71/1–71/10","big":"≤ 10","unit":"คน","hot":true,"ask":"ผู้ทรงคุณวุฒิใน ก.พ.ร. มีได้ไม่เกินกี่คน","sub":"ผู้ทรงคุณวุฒิไม่เกิน 10 คน วาระ 4 ปี","blocks":[{"k":"list","items":[{"icon":"👑","t":"ประธาน: นายกรัฐมนตรี","d":"หรือรองนายกรัฐมนตรีที่นายกฯ มอบหมาย"},{"icon":"🥈","t":"รองประธาน: รัฐมนตรี 1 คน","d":"ที่นายกรัฐมนตรีกำหนด"},{"icon":"🏘️","t":"ผู้ที่คณะกรรมการการกระจายอำนาจฯ มอบหมาย 1 คน"},{"icon":"🎓","t":"ผู้ทรงคุณวุฒิไม่เกิน 10 คน ครม. แต่งตั้ง","d":"ครม. ให้ 3–5 คนทำงานเต็มเวลาได้ · วาระ 4 ปี ติดต่อกั