  ('a3-admin2', 'A3', false, 1, '{"id":"a3-admin2","group":"A3","topics":["A3-ADMIN"],"icon":"🔁","title":"พ.ร.บ.ระเบียบบริหารราชการแผ่นดิน ② มอบอำนาจ รักษาราชการแทน & ภูมิภาค","hub":"ใครทำแทนใคร","hubSub":"หมวด 5–6 · ส่วนภูมิภาค","branches":[{"id":"delegate","icon":"✍️","tone":"pink","title":"มอบอำนาจ (ปฏิบัติราชการแทน)","ref":"ม.38–40","big":"หนังสือ","must":true,"ask":"การมอบอำนาจต้องทำอย่างไร","sub":"การมอบอำนาจต้องทำเป็นหนังสือ","blocks":[{"k":"steps","items":[{"t":"ผู้มีอำนาจมอบให้ผู้ดำรงตำแหน่งอื่น (ส่วนราชการเดียวกัน ส่วนราชการอื่น หรือผู้ว่าฯ) ปฏิบัติราชการแทน","d":"ถ้ากฎหมายไม่ได้ห้ามหรือกำหนดไว้เป็นอย่างอื่น · ตามหลักเกณฑ์ใน พ.ร.ฎ."},{"t":"ผู้รับมอบอำนาจ \"มีหน้าที่ต้องรับ\" ปฏิเสธไม่ได้","d":"ผู้มอบจะให้มอบต่อได้หรือไม่ ก็กำหนดได้ (ม.39)"},{"t":"ผู้มอบยังต้องกำกับ ติดตาม แนะนำ และแก้ไขการทำงานของผู้รับมอบได้ (ม.40)"}]},{"k":"pairs","items":[{"a":"ปฏิบัติราชการแทน","b":"ตัวจริงยังอยู่ แต่มอบอำนาจบางเรื่องให้ทำแทน · ต้องเป็นหนังสือ"},{"a":"รักษาราชการแทน","b":"ไม่มีตัวจริง หรือมีแต่ปฏิบัติราชการไม่ได้ · เกิดขึ้นเองตามกฎหมาย"}]},{"k":"note","t":"ทั้งผู้รักษาราชการแทนและผู้ปฏิบัติราชการแทน มีอำนาจหน้าที่เช่นเดียวกับผู้ที่ตนแทน รวมถึงการเป็นกรรมการตามกฎหมายอื่น (ม.48)"}]},{"id":"acting","icon":"🪜","tone":"mint","title":"รักษาราชการแทน ส่วนกลาง","ref":"ม.41–47","big":"รอง ➜ …","hot":true,"ask":"ไม่มีปลัดกระทรวงและรองปลัด ใครแต่งตั้งผู้รักษาราชการแทน","sub":"ไล่ลงทีละขั้น ถ้ามีรองหลายคนจึงมีคนแต่งตั้ง","blocks":[{"k":"table","head":["ตำแหน่งว่าง","ใครรักษาราชการแทน","ถ้ามีหลายคน / ไม่มี"],"rows":[["นายกรัฐมนตรี","รองนายกฯ","ครม. มอบหมายรองนายกฯ หรือรัฐมนตรีคนหนึ่ง"],["รัฐมนตรีว่าการกระทรวง","รัฐมนตรีช่วยฯ","ครม. มอบหมาย"],["เลขานุการรัฐมนตรี","ผู้ช่วยเลขานุการรัฐมนตรี","รัฐมนตรีว่าการกระทรวงมอบหมาย / แต่งตั้งข้าราชการในกระทรวง"],["ปลัดกระทรวง","รองปลัดกระทรวง","รัฐมนตรีว่าการแต่งตั้ง (ไม่ต่ำกว่าอธิบดี)"],["อธิบดี","รองอธิบดี","ปลัดกระทรวงแต่งตั้ง"],["เลขานุการกรม","—","อธิบดีแต่งตั้ง (ไม่ต่ำกว่าหัวหน้ากอง)"]]},{"k":"list","items":[{"icon":"📌","t":"ไม่มีรองปลัดกร