  ('b1-psy2', 'B1', false, 30, '{"id":"b1-psy2","group":"B1","topics":["B1-PSY"],"icon":"🧭","title":"จิตวิทยา ② สำนักคิด แรงจูงใจ เด็กพิเศษ & แนะแนว","hub":"จิตวิทยา ②","hubSub":"เรื่องที่ออกบ่อยนอกทฤษฎีหลัก","intro":"สำนักจิตวิทยา ฟรอยด์ การวางเงื่อนไขเชิงลึก แรงจูงใจและการถ่ายโยง เด็กที่มีความต้องการพิเศษ และการแนะแนว ทฤษฎีพัฒนาการหลักอยู่ในแผนผัง ①","branches":[{"id":"schools","icon":"🏛️","tone":"pink","title":"สำนักจิตวิทยา","big":"6","unit":"กลุ่ม","must":true,"sub":"โครงสร้าง · หน้าที่ · พฤติกรรม · เกสตัลท์ · จิตวิเคราะห์ · มนุษยนิยม","ask":"กลุ่มแนวคิดหลักทางจิตวิทยามีกี่กลุ่ม","blocks":[{"k":"table","head":["กลุ่ม","แนวคิด","บุคคล"],"rows":[["โครงสร้างทางจิต","จิตแยกเป็นส่วน 3 องค์ประกอบ: การสัมผัส ความรู้สึก มโนภาพ","วุนต์ (บิดาจิตวิทยาการทดลอง)"],["หน้าที่ทางจิต","จิตควบคุมกระบวนการทุกอย่างในร่างกาย ช่วยปรับตัว · 3 ป: ปัญหา ประสบการณ์ ปฏิบัติ","วิลเลียม เจมส์ · จอห์น ดิวอี้ (Learning by doing)"],["พฤติกรรมนิยม","ศึกษาเฉพาะพฤติกรรมที่สังเกตได้ · สิ่งเร้า-การตอบสนอง","วัตสัน"],["เกสตัลท์","ส่วนรวมมากกว่าผลรวมของส่วนย่อย · การหยั่งเห็น (Insight) อาศัยประสบการณ์เดิม","โคห์เลอร์ (ลิงต่อไม้) · เลวิน (ทฤษฎีสนาม Life Space)"],["จิตวิเคราะห์","จิตไร้สำนึก พฤติกรรมส่วนใหญ่มาจากแรงขับทางเพศ","ฟรอยด์"],["มนุษยนิยม","มนุษย์มีศักยภาพ พัฒนาตนเองได้สูงสุด","มาสโลว์ · โรเจอร์ส"]]},{"k":"steps","items":[{"t":"อธิบายพฤติกรรม","d":"ต่ำสุด"},{"t":"เข้าใจพฤติกรรม"},{"t":"ทำนายพฤติกรรม"},{"t":"ควบคุมพฤติกรรม","d":"สูงสุด"}]},{"k":"memo","t":"เป้าหมายของจิตวิทยา \"อธิบาย-เข้าใจ-ทำนาย-ควบคุม\""},{"k":"pairs","items":[{"a":"พฤติกรรมภายนอก","b":"โมลาร์ = เห็นด้วยตาเปล่า (ยิ้ม เดิน) · โมเลกุลาร์ = ต้องใช้เครื่องมือ (ความดันเลือด การไหลเวียนโลหิต)"},{"a":"พฤติกรรมภายใน","b":"ความคิด ความรู้สึก ความมุ่งมั่น สังเกตโดยตรงไม่ได้"}]}]},{"id":"freud","icon":"🧸","tone":"mint","title":"ฟรอยด์ & กลไกป้องกันตัว","big":"Superego","sub":"ส่วนที่คิดถึงผิดชอบชั่วดี","ask":"ส่วนของบุคลิกภาพที่คิดถึงผิดชอบชั่วดีตามแนวคิดของฟรอยด์คืออะไร","blocks":[{"k":"table","head":["ส่วน","ทำงานตาม","หน้าที่"],"ro