  ('b3-ind-safety', 'B3', true, 45, '{"group":"B3","topics":["B3-INDART"],"id":"b3-ind-safety","subtopics":["B3-INDART-SAFETY"],"icon":"🦺","free":true,"title":"ความปลอดภัยในโรงฝึกงาน","hub":"ความปลอดภัย","hubSub":"อุบัติเหตุ · สี · ไฟ · แก๊ส · ไฟฟ้า","intro":"หมวดนี้คนทำได้ดีที่สุดของวิชาเอก แต่ประเภทเพลิง สีความปลอดภัย และระยะทางเดินยังผิดกันเยอะ","branches":[{"id":"cause","icon":"👷","tone":"pink","title":"สาเหตุอุบัติเหตุ","ref":"ทฤษฎีโดมิโน (Heinrich)","big":"88 : 10 : 2","unit":"%","must":true,"sub":"คน · สภาพแวดล้อม · สุดวิสัย","ask":"อุบัติเหตุในโรงงานเกิดจากอะไรมากที่สุด กี่เปอร์เซ็นต์","blocks":[{"k":"table","head":["สาเหตุ","สัดส่วน","ตัวอย่าง"],"rows":[["การกระทำที่ไม่ปลอดภัย (คน)","≈ 88%","ไม่สวมอุปกรณ์ป้องกัน ทำงานลัดขั้นตอน หยอกล้อ ใช้เครื่องมือผิดวิธี"],["สภาพแวดล้อมที่ไม่ปลอดภัย","≈ 10%","เครื่องจักรไม่มีที่ครอบ แสงไม่พอ พื้นลื่น ของวางเกะกะ"],["เหตุสุดวิสัย","≈ 2%","ภัยธรรมชาติ"]]},{"k":"steps","items":[{"t":"ภูมิหลังและสภาพแวดล้อมของคน"},{"t":"ความบกพร่องของบุคคล"},{"t":"การกระทำ/สภาพที่ไม่ปลอดภัย","d":"ตัวโดมิโนที่ดึงออกได้ง่ายที่สุด"},{"t":"อุบัติเหตุ"},{"t":"การบาดเจ็บหรือความเสียหาย"}]},{"k":"memo","t":"\"คนเป็นต้นเหตุ\" ตอบ \"คน\" ไว้ก่อน เมื่อถามสาเหตุหลักของอุบัติเหตุ"}]},{"id":"color","icon":"🎨","tone":"mint","title":"สีและเครื่องหมาย","ref":"มอก. 635 · ISO 3864","big":"4","unit":"สีหลัก","hot":true,"sub":"แดง ห้าม · น้ำเงิน บังคับ · เหลือง ระวัง · เขียว ปลอดภัย","ask":"สีความปลอดภัย 4 สีหลักหมายถึงอะไร","blocks":[{"k":"table","head":["สี","ความหมาย","รูปทรงป้าย"],"rows":[["แดง","ห้าม หยุด · อุปกรณ์ดับเพลิง","วงกลมมีขีดทับ"],["น้ำเงิน","บังคับให้ปฏิบัติ เช่น ต้องสวมแว่น","วงกลมทึบ"],["เหลือง","ระวังอันตราย · ตีกรอบพื้นที่เครื่องจักร","สามเหลี่ยม"],["เขียว","สภาวะปลอดภัย ทางหนีไฟ ปฐมพยาบาล","สี่เหลี่ยม"]]},{"k":"pairs","items":[{"a":"ตีกรอบเครื่องจักร / แนวอันตรายบนพื้น","b":"สีเหลือง (หรือเหลืองสลับดำ)"},{"a":"เขตทางเดิน / จราจรในโรงงาน","b":"สีขาว (หรือขาวสลับดำ)"},{"a":"ห้องเขียนแบบ ห้องที่ใช้สายตาและความคิด","b":"สีเขียวอ่อน สบายตา"},{"a"